#!/bin/bash
set -euo pipefail
test "$(id -un)" = pwa209
case "$(hostname -f)" in *.narval.calcul.quebec) ;; *) exit 2 ;; esac
module load StdEnv/2023 python/3.11.5 cuda/12.6 arrow/19.0.1
source /home/pwa209/hhw-environment/bin/activate
export PYTHONPATH=/scratch/pwa209/horsehair-worm/releases/20261021-6ed201653dfa-4f3903d7c26e/src
export PYTHONDONTWRITEBYTECODE=1 TZ=UTC
python -B -u - <<'PY'
from pathlib import Path
import base64,hashlib,json,os,shlex,subprocess,zlib
from horsehair import slurm
from horsehair.core import read_json,canonical_hash,source_identity,atomic_json,exclusive_file_lock
assert os.geteuid()==3164768
r=Path('/scratch/pwa209/horsehair-worm');s=r/'maintenance/finite-resume-handoff-v2-20261103'
assert not s.exists() and not (r/'plans/finite-resume-handoff-v2-20261103').exists() and not (r/'state/finite-resume-handoff-v2-20261103-submission.json').exists(),'Prior publication must be reconciled, never replayed'
print('FINITE_HANDOFF_NAMESPACE_UNUSED: no support, plan or ledger exists before staging',flush=True)
payload={'hhw-primary-resume-20261103-902.sh': {'sha256': '116968a91e1daf8ef065e6fb1c2a36c1287301165bcbd522146d89349cedc85f', 'bytes': 7146, 'data': ''}, 'hhw-agent-resume-v8-20261103-900.sh': {'sha256': 'fc8623b636d72e2a6645eb50075fcbc04a55951fb9e5ffac9ad3eae2f22a1969', 'bytes': 7909, 'data': ''}, 'handoff.py': {'sha256': '6d374e58ad7c2f420ae5edbb6bdab07f9ea4193f388e95a433cfa9805f70abaa', 'bytes': 5439, 'data': ''}}
requirements={'primary': {'record': '/scratch/pwa209/horsehair-worm/maintenance/study-census-resilience-consumers-v5-20261103/qualification-registration/registration.json', 'manifest': {'path': '/scratch/pwa209/horsehair-worm/maintenance/study-census-resilience-consumers-v5-20261103/source-manifest.json', 'sha256': '4b043a5906385a05fd2c0ea4525a8a6b978f70dbae344b4e2a603a6d5f8315ab'}}, 'agent': {'record': '/scratch/pwa209/horsehair-worm/maintenance/agent-coordination-repair-v8-20261103/qualification-registration.json', 'manifest': {'path': '/scratch/pwa209/horsehair-worm/maintenance/agent-coordination-repair-v8-20261103/source-manifest.json', 'sha256': 'e8a77557e9ffdbeb35c834b8aab6ad1b01874e381d677df1d3d7a6e8527ac725'}}}
qids={}
for label,item in requirements.items():
 manifest=item['manifest'];assert hashlib.sha256(Path(manifest['path']).read_bytes()).hexdigest()==manifest['sha256']
 receipt=read_json(item['record'])
 if label=='primary':
  assert receipt['status']=='native_consumer_qualification_registered_and_released' and receipt['source_manifest']==manifest
 else:
  assert receipt['status']=='registered_and_released_qualification' and receipt['source_manifest_sha256']==manifest['sha256']
 job=receipt['job_id'];assert isinstance(job,str) and job.isdecimal() and int(job)>0
 qids[label]=job
assert len(set(qids.values()))==2 and '6983037' not in qids.values()
item=payload['handoff.py'];raw=zlib.decompress(base64.b64decode(item['data']))
assert hashlib.sha256(raw).hexdigest()==item['sha256'] and len(raw)==item['bytes']
for token,label in [('__HHW_PRIMARY_Q__','primary'),('__HHW_AGENT_Q__','agent')]:
 assert raw.count(token.encode())==1
 raw=raw.replace(token.encode(),qids[label].encode())
compile(raw,'source-bound-finite-handoff','exec')
item.update(sha256=hashlib.sha256(raw).hexdigest(),bytes=len(raw),data=base64.b64encode(zlib.compress(raw,9)).decode())

s.mkdir(mode=0o700,exist_ok=False)
for name,item in payload.items():
 raw=zlib.decompress(base64.b64decode(item['data']));assert len(raw)==item['bytes'] and hashlib.sha256(raw).hexdigest()==item['sha256']
 with (s/name).open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
 (s/name).chmod(0o444)
framework=r/'releases/20261021-6ed201653dfa-4f3903d7c26e';config=read_json(framework/'configs/study.json')
assert source_identity(framework)['sha256']=='4f3903d7c26e334a75c8f7f81ad8b865fac4e5a447ff83a8bfeae8774891d9d1'
phase='finite-resume-handoff-v2-20261103';directory=r/'plans'/phase;ledger=r/'state'/(phase+'-submission.json')
assert not directory.exists() and not ledger.exists();directory.mkdir()
name='finite-primary-agent-resume-handoff';script=directory/(name+'.sbatch')
argv=['python','-B',str(s/'handoff.py'),'--source-sha256',payload['handoff.py']['sha256'],'--native-plan',str(directory/'plan.json'),'--native-ledger',str(ledger),'--native-script',str(script),'--native-task',name]
text=slurm._script(config,framework,name,shlex.join(argv),cpus=2,memory='16G',hours=2,gpu=False).replace('set -euo pipefail','#SBATCH --hold\n#SBATCH --no-requeue\nset -euo pipefail',1)
script.write_text(text)
task={'name':name,'script':str(script),'script_sha256':canonical_hash(text),'depends':[],'external_dependencies':[qids['primary'],qids['agent'],'6983037'],'dependency_kind':'afterok','resources':{'cpus':2,'memory':'16G','hours':2,'gpu':False,'array':None},'command':shlex.join(argv),'finite_resume_handoff':{'source_sha256':payload['handoff.py']['sha256'],'children':{n:payload[n]['sha256'] for n in ['hhw-primary-resume-20261103-902.sh','hhw-agent-resume-v8-20261103-900.sh']},'maximum_accounting_wait_seconds':900,'persistent':False}}
plan={'schema_version':1,'root':str(r),'phase':phase,'release_identity':source_identity(framework),'config_sha256':canonical_hash(config),'tasks':[task]};atomic_json(directory/'plan.json',plan)
counter=[0]
def runner(cmd,**kw):
 counter[0]+=1;prefix=s/('mutation-'+str(counter[0]));atomic_json(Path(str(prefix)+'-intent.json'),{'command':cmd,'automatic_replay_permitted':False})
 result=subprocess.run(cmd,**kw,timeout=90);atomic_json(Path(str(prefix)+'-response.json'),{'returncode':result.returncode,'stdout':result.stdout,'stderr':result.stderr});return result
def observe(job):
 p=subprocess.run(['scontrol','show','job',job,'-o'],text=True,capture_output=True,timeout=90);p.check_returncode();assert not p.stderr
 return dict(x.split('=',1) for x in shlex.split(p.stdout) if '=' in x)
with exclusive_file_lock(r/'state/af-campaign-registration.mutex',timeout=180):
 record=slurm.submit(directory/'plan.json',ledger,runner=runner);job=record['tasks'][name]['job_id'];f=observe(job)
 assert f['JobId']==job and f['UserId']=='pwa209(3164768)' and f['JobState']=='PENDING' and f['Reason']=='JobHeldUser'
 assert f['Command']==str(script) and f['JobName']=='hhw-'+name and f['Account']=='def-ptewarie_cpu' and f['NumCPUs']=='2' and f['MinMemoryNode'] in {'16G','16384M'} and f['TimeLimit']=='02:00:00'
 assert f['Requeue']=='0';atomic_json(s/'held-native.json',f)
runner(['scontrol','release',job],text=True,capture_output=True);f=observe(job)
assert f['JobId']==job and f['UserId']=='pwa209(3164768)' and f['Command']==str(script)
assert f['JobState'] in {'RUNNING','COMPLETING','COMPLETED'} or f['JobState']=='PENDING' and f['Reason'] not in {'JobHeldUser','JobHeldAdmin'} and int(f['Priority'])>0
receipt={'status':'one_finite_administrative_handoff_queued','job_id':job,'dependencies':[qids['primary'],qids['agent'],'6983037'],'plan':str(directory/'plan.json'),'ledger':str(ledger),'source_sha256':payload['handoff.py']['sha256'],'children':task['finite_resume_handoff']['children'],'actual_unheld_native':f,'persistent':False}
atomic_json(s/'registration.json',receipt);print('FINITE_HANDOFF_903 '+json.dumps(receipt),flush=True)

PY
